package com.example.starter.batch.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.time.Instant;
import java.util.List;

/**
 * 创建条件放行请求。仅对已通过全部必做检验但尚未批准（PENDING_RELEASE，
 * 或上一条条件放行已到期降级）的批次有效。
 *
 * @param commandKey 创建命令幂等键
 * @param conditionKey 条件放行业务键，全局唯一，只能被创建一次
 * @param expiresAt 条件有效期到期时刻（UTC），必须晚于当前时刻
 * @param conditions 1～5 条条件子项说明
 */
public record CreateConditionRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "conditionKey 不能为空") String conditionKey,
        @NotNull(message = "expiresAt 不能为空") Instant expiresAt,
        @NotNull(message = "conditions 不能为空")
        @Size(min = 1, max = 5, message = "conditions 必须包含 1～5 条条件说明")
        List<@Valid ConditionItemInput> conditions
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 条件放行子项输入：conditionKey 内的子项标识与条件说明。
 */
public record ConditionItemInput(
        @NotBlank(message = "条件子项 itemKey 不能为空")
        @Size(max = 64, message = "条件子项 itemKey 最长 64 字符")
        String itemKey,
        @NotBlank(message = "条件说明不能为空")
        @Size(max = 512, message = "条件说明最长 512 字符")
        String description
) {
}

package com.example.starter.batch.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 核销条件子项请求：逐条提交 conditionKey 内子项标识与证明说明；
 * 核销批准角色必须与创建条件放行时的角色不同。
 */
public record CloseConditionRequest(
        @NotBlank(message = "commandKey 不能为空") String commandKey,
        @NotBlank(message = "itemKey 不能为空") String itemKey,
        @NotBlank(message = "evidence 证明说明不能为空")
        @Size(max = 512, message = "evidence 最长 512 字符")
        String evidence
) {
}

package com.example.starter.batch.dto;

import com.example.starter.batch.BatchStatus;

import java.time.Instant;
import java.util.List;

/**
 * 条件放行明细：包含创建信息、到期状态（expired 按可注入时钟实时判定，不依赖后台任务）、
 * 逐条子项及其核销状态。items 按 seq 稳定排序。
 *
 * @param batchKey 所属批次业务键
 * @param conditionKey 条件放行业务键
 * @param creatorId 创建批准人标识
 * @param creatorRole 创建批准角色，核销角色必须与之不同
 * @param expiresAt 条件有效期到期时刻（UTC）
 * @param createdAt 创建时刻（UTC）
 * @param expired 当前时钟下是否已到期
 * @param batchStatus 查询时的批次状态
 * @param items 条件子项明细，按 seq 升序
 */
public record ConditionReleaseResponse(
        String batchKey,
        String conditionKey,
        String creatorId,
        String creatorRole,
        Instant expiresAt,
        Instant createdAt,
        boolean expired,
        BatchStatus batchStatus,
        List<ConditionItemResponse> items
) {
}

