            "SELECT * FROM batch b WHERE b.status <> 'RECALLED'"
                    + " AND NOT (b.status = 'CONDITIONAL' AND EXISTS ("
                    + " SELECT 1 FROM conditional_release c"
                    + " WHERE c.batch_key = b.batch_key AND c.expires_at <= ?))"
                    + " ORDER BY b.id",
            BATCH_MAPPER, nowIso);
}

