                        + " WHERE c.batch_key = b.batch_key AND c.expires_at <= ?))"
                        + " ORDER BY b.id",
                BATCH_MAPPER, nowIso);
    }

    public Optional<TestRow> findTest(String batchKey, String testKey) {
        return jdbc.query("SELECT * FROM test_result WHERE batch_key = ? AND test_key = ?",
