        preparePendingBatch(batchKey, List.of("t1"));

        // 同一 commandKey 同参重试 → 首次成功结果 201
        MvcResult first = mockMvc.perform(post("/api/batches/" + batchKey + "/conditions")
                .header("X-Actor-Id", "qa-2").header("X-Approval-Role", "QUALITY")
