        Integer logged = jdbc.queryForObject(
                "SELECT COUNT(*) FROM command_log WHERE command_type = 'CREATE_CONDITION'"
                        + " AND command_key = 'CK-IDEM-1'", Integer.class);
        assertEquals(1, logged);
    }

